/**
 * The client-supplied KKR Diagnostic Centre letterhead ("demo sheet.jpeg"),
 * used verbatim as the full A4 page background for lab reports, case
 * sheets, charge sheets and the patient-charges PDF — rather than
 * redrawing the logo/name/watermark/footer by hand, which drifted from the
 * real artwork (wrong logo crop, wrong name font, wrong phone size, a tint
 * introduced by our own transparency compositing).
 *
 * Image is 1132x1600px, aspect ratio 0.7075 — close enough to A4's 0.7071
 * that scaling it to 210x297mm is not perceptibly distorted.
 */
export const KKR_LETTERHEAD_BG_DATA_URI = 'data:image/jpeg;base64,'

/** Detected from the artwork: header rule and footer band pixel rows, out of 1600px tall. */
export const LETTERHEAD_PX = {
  imageWidth: 1132,
  imageHeight: 1600,
  headerRuleY: 215,
  footerBandStartY: 1553,
}
